  "code": "def from_environ(cls, environ, **kwargs):
        """Turn an environ dict back into a builder. Any extra kwargs
        override the args extracted from the environ.

        .. versionadded:: 0.15
        """
        builder = cls()
        for key, value in environ.items():
            if key.startswith('HTTP_') and key != 'HTTP_CONTENT_LENGTH':
                header_key = key[5:].replace('_', '-')
                builder.headers[header_key] = value
            elif key in ('CONTENT_TYPE', 'CONTENT_LENGTH'):
                setattr(builder, key.lower(), value)
            elif key == 'REQUEST_METHOD':
                builder.method = value
            elif key == 'PATH_INFO':
                builder.path = value
            elif key == 'QUERY_STRING':
                builder.query_string = value
        builder.environ_base = environ
        builder.environ_overrides = kwargs
        return builder"
}

