  "code": "def is_resource_modified(environ, etag=None, data=None, last_modified=None):
    # Check if the request method is GET or HEAD
    if environ.get('REQUEST_METHOD') not in ('GET', 'HEAD'):
        return False

    # Check If-None-Match header
    if_none_match = parse_etags(environ.get('HTTP_IF_NONE_MATCH'))
    if if_none_match:
        if if_none_match(etag=etag, data=data):
            return False

    # Check If-Modified-Since header
    if_modified_since = parse_date(environ.get('HTTP_IF_MODIFIED_SINCE'))
    if if_modified_since and last_modified:
        if last_modified <= if_modified_since:
            return False

    return True"
}

